      outline: 3px solid rgba(109, 93, 252, 0.32);
      outline-offset: -6px;
    }

    @media (max-width: 640px) {
      main {
        width: min(100% - 20px, 920px);
        padding: 40px 0;
      }

      .faq-card {
        border-radius: 22px;
      }

      .question {
